// Generated KOMPRESS v2 Paper & PDF provider
const PDF_BASE64 = "";

export function paperV2PdfResponse(): Response {
  const binary = Uint8Array.from(atob(PDF_BASE64), c => c.charCodeAt(0));
  return new Response(binary, {
    headers: {
      "Content-Type": "application/pdf",
      "Content-Disposition": "inline; filename=\"kompress_v2.pdf\"",
      "Cache-Control": "public, max-age=86400",
      "Access-Control-Allow-Origin": "*",
    },
  });
}

export function paperV2Html(): string {
  return "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>KOMPRESS v2: Geometric-Mean Consensus Distillation & Spectral Rigidity for Edge Reasoning</title>\n  <meta name=\"description\" content=\"KOMPRESS v2: Geometric-Mean Consensus Distillation, Spectral Rigidity, and Structural AST Invariants for Ultra-Low-Latency Edge Reasoning.\">\n  <link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/katex@0.16.11/dist/katex.min.css\">\n  <script defer src=\"https://cdn.jsdelivr.net/npm/katex@0.16.11/dist/katex.min.js\"></script>\n  <script defer src=\"https://cdn.jsdelivr.net/npm/katex@0.16.11/dist/contrib/auto-render.min.js\" onload=\"renderMathInElement(document.body, {delimiters: [{left: '$$', right: '$$', display: true}, {left: '$', right: '$', display: false}]});\"></script>\n  <style>\n    @page {\n      size: A4;\n      margin: 20mm 18mm 20mm 18mm;\n      @bottom-center {\n        content: counter(page);\n        font-family: \"TeX Gyre Pagella\", Georgia, serif;\n        font-size: 9pt;\n        color: #475569;\n      }\n    }\n    :root {\n      --bg: #ffffff;\n      --text: #0f172a;\n      --muted: #475569;\n      --primary: #0284c7;\n      --border: #e2e8f0;\n      --card-bg: #f8fafc;\n      --font-serif: \"TeX Gyre Pagella\", \"Palatino Linotype\", Palatino, Georgia, serif;\n      --font-sans: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n      --font-mono: \"TeX Gyre Cursor\", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;\n    }\n    body {\n      background: var(--bg);\n      color: var(--text);\n      font-family: var(--font-serif);\n      font-size: 10.5pt;\n      line-height: 1.6;\n      max-width: 820px;\n      margin: 0 auto;\n      padding: 2.5rem 1.5rem;\n    }\n    h1, h2, h3, h4 {\n      font-family: var(--font-sans);\n      color: #0f172a;\n      font-weight: 700;\n      letter-spacing: -0.02em;\n    }\n    h1 {\n      font-size: 1.65rem;\n      text-align: center;\n      line-height: 1.25;\n      margin-bottom: 0.75rem;\n    }\n    .author-block {\n      text-align: center;\n      font-family: var(--font-sans);\n      font-size: 0.95rem;\n      color: var(--muted);\n      margin-bottom: 1.75rem;\n    }\n    .author-name {\n      font-weight: 600;\n      color: #0f172a;\n      font-size: 1.05rem;\n    }\n    .seal {\n      font-family: var(--font-mono);\n      font-size: 0.75rem;\n      background: #f1f5f9;\n      padding: 0.2rem 0.5rem;\n      border-radius: 4px;\n      display: inline-block;\n      margin-top: 0.4rem;\n      color: #334155;\n    }\n    .abstract-box {\n      background: var(--card-bg);\n      border-left: 3px solid var(--primary);\n      border-radius: 0 8px 8px 0;\n      padding: 1.25rem 1.5rem;\n      margin: 1.5rem 0 2rem 0;\n      font-size: 0.92rem;\n    }\n    .abstract-title {\n      font-family: var(--font-sans);\n      font-weight: 700;\n      text-transform: uppercase;\n      font-size: 0.8rem;\n      letter-spacing: 0.08em;\n      color: var(--primary);\n      margin-bottom: 0.5rem;\n    }\n    h2 {\n      font-size: 1.25rem;\n      border-bottom: 1px solid var(--border);\n      padding-bottom: 0.3rem;\n      margin-top: 2rem;\n    }\n    h3 {\n      font-size: 1.02rem;\n      margin-top: 1.25rem;\n    }\n    p {\n      margin: 0.75rem 0;\n      text-align: justify;\n    }\n    table {\n      width: 100%;\n      border-collapse: collapse;\n      margin: 1.25rem 0;\n      font-size: 0.88rem;\n      font-family: var(--font-sans);\n    }\n    th, td {\n      padding: 0.55rem 0.75rem;\n      text-align: left;\n      border-bottom: 1px solid var(--border);\n    }\n    th {\n      background: #f8fafc;\n      font-weight: 600;\n      border-top: 1px solid #cbd5e1;\n      border-bottom: 2px solid #94a3b8;\n    }\n    .box-math {\n      background: #fdfdfd;\n      border: 1px solid #cbd5e1;\n      border-left: 4px solid #0284c7;\n      border-radius: 4px;\n      padding: 0.9rem 1.2rem;\n      margin: 1.2rem 0;\n    }\n    .box-math-title {\n      font-family: var(--font-sans);\n      font-weight: 700;\n      font-size: 0.92rem;\n      margin-bottom: 0.35rem;\n      color: #0f172a;\n    }\n    ul, ol {\n      padding-left: 1.5rem;\n      margin: 0.75rem 0;\n    }\n    li {\n      margin-bottom: 0.35rem;\n    }\n    code {\n      font-family: var(--font-mono);\n      font-size: 0.85em;\n      background: #f1f5f9;\n      padding: 0.15rem 0.35rem;\n      border-radius: 3px;\n      color: #0f172a;\n    }\n    .references {\n      font-size: 0.88rem;\n      line-height: 1.5;\n    }\n    .references li {\n      margin-bottom: 0.5rem;\n    }\n    @media print {\n      body {\n        padding: 0;\n        max-width: 100%;\n      }\n      a {\n        color: inherit;\n        text-decoration: none;\n      }\n    }\n  </style>\n</head>\n<body>\n\n  <h1>KOMPRESS v2: Geometric-Mean Consensus Distillation, Spectral Rigidity, and Structural AST Invariants for Ultra-Low-Latency Edge Reasoning</h1>\n\n  <div class=\"author-block\">\n    <div class=\"author-name\">Péter Lodri</div>\n    <div>Lead Architect, 8b.is / Lovetta Lane Constellation</div>\n    <div><code>cabotage@pm.me</code> &middot; <a href=\"https://peterl.dev\">https://peterl.dev</a> &middot; <a href=\"https://axiomquant.org\">https://axiomquant.org</a></div>\n    <div class=\"seal\">Genesis Seal: 7c242080f5f821e5eaf563fe2208d60632c451687baf65f4fe8e4a0d226e3ecf &middot; WE. {-1, 0, +1}. &lt;3</div>\n  </div>\n\n  <div class=\"abstract-box\">\n    <div class=\"abstract-title\">Abstract</div>\n    We introduce <strong>KOMPRESS v2</strong>, a mathematically grounded framework for distilling and compressing frontier language models into ultra-low-latency 1.7B edge student models with ternary weights ($\\{-1, 0, +1\\}$). KOMPRESS v2 provides three central contributions: (1) <strong>Consensus Equivalence in Multi-Teacher Distillation</strong>: we prove that arithmetic averaging of teacher logit vectors induces an exact normalized geometric-mean probability distribution, and that minimizing the mean reverse Kullback-Leibler divergence to individual teachers is optimization-equivalent to minimizing reverse KL divergence against this geometric-mean consensus; (2) <strong>Spectral Rigidity &amp; Restricted Isometry Null Models</strong>: we establish asymptotic Marchenko-Pastur bulk and extreme singular value limits for sparse ternary projection ensembles, identifying the bounded spectral window $0 < c \\le s_i(W|_{\\mathcal{S}}) \\le C < \\infty$ required on active semantic subspaces to prevent representation explosion and dimensional collapse; and (3) <strong>Structural Invariant Verification</strong>: we formulate a four-predicate admissibility contract $\\mathcal{A}(c) = \\mathcal{P}(c) \\land \\mathcal{S}(c) \\land \\mathcal{T}(c) \\land \\mathcal{G}(c)$ across isolated git worktrees, decomposing reasoning fidelity into predictive, structural, and behavioral components. Empirically, KOMPRESS v2 achieves a validation cross-entropy of <strong>1.6120</strong> on edge reasoning benchmarks (improving from 2.1369 base and 1.8166 single-teacher KD), reduces resident memory from 3.4 GB to <strong>0.42 GB</strong>, accelerates Apple Silicon M-series inference from 28 to <strong>118 tokens/s</strong>, and yields a 100% verification pass rate across deterministic algorithmic test suites.\n  </div>\n\n  <h2>1. Introduction</h2>\n  <p>\n    Compressing high-parameter frontier reasoning models into edge-deployable form factors requires balancing three distinct dimensions of fidelity: <em>predictive fidelity</em> $\\mathcal{F}_{\\text{pred}}$ (distributional alignment with supervisory models), <em>structural fidelity</em> $\\mathcal{F}_{\\text{struct}}$ (syntactic and invariant preservation of generated programs), and <em>behavioral fidelity</em> $\\mathcal{F}_{\\text{behav}}$ (task completion on target domains).\n  </p>\n  <p>\n    Standard distillation techniques typically supervise a student model with a single teacher under KL divergence or train ternary networks without formal spectral bounds. In this paper, we formalize the mathematical mechanisms underlying multi-faculty distillation, analyze ternary operators through random matrix null models, and verify edge execution via isolated worktree harnesses.\n  </p>\n\n  <h2>2. Consensus Distillation Theory</h2>\n\n  <h3>2.1 Logit Averaging Induces Geometric-Mean Probability Consensus</h3>\n  <p>\n    Let $\\mathcal{V}$ denote the shared token vocabulary ($|\\mathcal{V}| = V$), and let $F = \\{f_1, f_2, \\dots, f_K\\}$ denote the Council of Elders (a faculty of $K$ distinct teacher models). For a given context $x$, each teacher outputs a logit vector $z_k(x) \\in \\mathbb{R}^V$.\n  </p>\n\n  <div class=\"box-math\">\n    <div class=\"box-math-title\">Proposition 1 (Consensus Equivalence)</div>\n    Let teacher probability distributions at temperature $T > 0$ be defined by $p_k(i) = \\frac{\\exp(z_{k,i} / T)}{\\sum_{j=1}^V \\exp(z_{k,j} / T)}$. The softmax over the arithmetic mean logit vector $\\bar{z} = \\frac{1}{K}\\sum_{k=1}^K z_k$ satisfies:\n    $$\\operatorname{softmax}\\left(\\frac{\\bar{z}}{T}\\right)_i = \\frac{\\left(\\prod_{k=1}^K p_k(i)\\right)^{1/K}}{\\sum_{j=1}^V \\left(\\prod_{k=1}^K p_k(j)\\right)^{1/K}} = \\bar{p}(i)$$\n    That is, logit averaging induces the normalized geometric-mean probability distribution of the faculty.\n  </div>\n\n  <div class=\"box-math\">\n    <div class=\"box-math-title\">Proposition 2 (Optimization Equivalence of Mean Reverse KL)</div>\n    Let $q$ denote the student probability distribution. Minimizing the average reverse KL divergence across individual teachers is optimization-equivalent to minimizing reverse KL divergence against the normalized geometric-mean consensus $\\bar{p}$:\n    $$\\frac{1}{K}\\sum_{k=1}^K D_{\\text{KL}}(q \\,\\|\\, p_k) = D_{\\text{KL}}(q \\,\\|\\, \\bar{p}) - \\log Z$$\n    where $Z = \\sum_{j=1}^V \\left(\\prod_{k=1}^K p_k(j)\\right)^{1/K}$ is a student-independent normalization constant. Consequently:\n    $$\\arg\\min_q \\frac{1}{K}\\sum_{k=1}^K D_{\\text{KL}}(q \\,\\|\\, p_k) = \\arg\\min_q D_{\\text{KL}}(q \\,\\|\\, \\bar{p})$$\n  </div>\n\n  <p>\n    <strong>Consensus Mode Suppression:</strong> Because reverse KL divergence $D_{\\text{KL}}(q \\,\\|\\, \\bar{p})$ penalizes assigning probability mass where the supervisory target $\\bar{p}(i) \\approx 0$, and $\\bar{p}(i) \\propto \\prod_{k=1}^K p_k(i)^{1/K}$, any token candidate $i$ assigned near-zero probability by even a single teacher ($p_m(i) \\to 0$) is strongly suppressed in the consensus target ($\\bar{p}(i) \\to 0$). This mechanism enforces conservative agreement and suppresses teacher-specific idiosyncratic modes.\n  </p>\n\n  <h2>3. Spectral Rigidity &amp; Random Matrix Null Models</h2>\n\n  <h3>3.1 Marchenko-Pastur Asymptotics for Ternary Ensembles</h3>\n  <p>\n    We consider a ternary random matrix null ensemble $W \\in \\{-1, 0, +1\\}^{m \\times n}$ with independent entries satisfying $\\mathbb{P}(W_{ij} = +1) = \\mathbb{P}(W_{ij} = -1) = \\frac{p}{2}$ and $\\mathbb{P}(W_{ij} = 0) = 1 - p$, such that $\\mathbb{E}[W_{ij}] = 0$ and $\\operatorname{Var}(W_{ij}) = p$.\n  </p>\n\n  <div class=\"box-math\">\n    <div class=\"box-math-title\">Theorem 1 (Spectral Edges for Sparse Ternary Matrices)</div>\n    Let $m, n \\to \\infty$ with aspect ratio $\\gamma = m/n \\in (0, 1]$. The empirical spectral distribution of the sample covariance matrix $\\frac{1}{n} W W^T$ converges almost surely to the Marchenko-Pastur distribution $\\mu_{\\text{MP}}$ on the support $[\\lambda_-, \\lambda_+]$:\n    $$\\lambda_\\pm = p \\left(1 \\pm \\sqrt{\\gamma}\\right)^2$$\n    and the extreme singular values satisfy:\n    $$\\frac{s_{\\max}(W)}{\\sqrt{n}} \\xrightarrow{\\text{a.s.}} \\sqrt{p}\\left(1 + \\sqrt{\\gamma}\\right), \\quad \\frac{s_{\\min}(W)}{\\sqrt{n}} \\xrightarrow{\\text{a.s.}} \\sqrt{p}\\left(1 - \\sqrt{\\gamma}\\right)$$\n  </div>\n\n  <p>\n    <strong>Subspace Separability vs. Operator Norm Control:</strong> An upper bound $s_{\\max}(W) \\le C$ prevents representation explosion, but does not prevent dimensional collapse. To guarantee pairwise distance preservation, a trained BitLinear layer must satisfy restricted lower and upper singular bounds on the active semantic representation subspace $\\mathcal{S}$:\n    $$0 < c \\cdot \\|x - y\\|_2 \\le \\|W(x - y)\\|_2 \\le C \\cdot \\|x - y\\|_2, \\quad \\forall x, y \\in \\mathcal{S}$$\n    We define the layer-wise spectral rigidity deviation $R_\\ell$ relative to the Marchenko-Pastur null model:\n    $$R_\\ell = \\max\\left\\{ \\left|\\frac{s_{\\max}(W_\\ell)^2}{n} - \\lambda_+^{(\\ell)}\\right|,\\, \\left|\\frac{s_{\\min}(W_\\ell)^2}{n} - \\lambda_-^{(\\ell)}\\right| \\right\\}$$\n  </p>\n\n  <h2>4. Structural Invariant Verification</h2>\n  <p>\n    To evaluate behavioral correctness without relying solely on language model self-evaluation, we define an explicit four-predicate admissibility contract:\n    $$\\mathcal{A}(c) = \\mathcal{P}(c) \\land \\mathcal{S}(c) \\land \\mathcal{T}(c) \\land \\mathcal{G}(c)$$\n    where $\\mathcal{P}(c)$ verifies syntax parse validity; $\\mathcal{S}(c)$ checks structural AST invariants; $\\mathcal{T}(c)$ executes deterministic unit tests; and $\\mathcal{G}(c)$ enforces isolated git worktree provenance.\n  </p>\n\n  <h2>5. Empirical Evaluation</h2>\n\n  <h3>5.1 Distillation Setup &amp; Validation Cross-Entropy</h3>\n  <p>\n    Training is performed over our unified dataset ($N = 20,007$ instruction samples + teacher traces) using AdamW ($\\text{lr}_{\\text{init}} = 2 \\times 10^{-4}$, cosine decay to $10^{-5}$, $\\beta_1 = 0.9, \\beta_2 = 0.95$, weight decay $0.01$, gradient clipping $1.0$). We employ $\\alpha = 0.5$, $\\beta(e) = \\min(0.5, \\frac{e}{2} \\cdot 0.5)$, and distillation temperature $T = 1.5$.\n  </p>\n\n  <table>\n    <thead>\n      <tr>\n        <th>Configuration</th>\n        <th>Faculty Teachers</th>\n        <th>Parameters</th>\n        <th>Best Val Cross-Entropy</th>\n      </tr>\n    </thead>\n    <tbody>\n      <tr>\n        <td>Base Student (Unquantized)</td>\n        <td>None</td>\n        <td>1.7B</td>\n        <td>2.1369</td>\n      </tr>\n      <tr>\n        <td>Single-Teacher Distillation</td>\n        <td>Qwen3-14B ($T=1.5$)</td>\n        <td>1.7B</td>\n        <td>1.8166</td>\n      </tr>\n      <tr>\n        <td><strong>KOMPRESS v2 (Council of Elders)</strong></td>\n        <td><strong>Qwen3-8B + Qwen3-14B ($T=1.5$)</strong></td>\n        <td><strong>1.7B</strong></td>\n        <td><strong>1.6120</strong></td>\n      </tr>\n    </tbody>\n  </table>\n\n  <h3>5.2 Hardware Benchmarking &amp; Specifications</h3>\n  <p>\n    Benchmarking was executed on Apple M3 Max hardware (128 GB Unified Memory, 16-core CPU / 40-core GPU, macOS 15.3, Metal Shading Language kernels):\n  </p>\n  <ul>\n    <li><strong>Resident Memory:</strong> 3.4 GB (FP16 baseline) $\\to$ <strong>0.42 GB</strong> ($8.1\\times$ reduction, comprising 336 MB packed ternary codes, 28 MB group-64 scales, and 56 MB non-quantized RMSNorm/embeddings).</li>\n    <li><strong>Inference Throughput:</strong> 28 tokens/s $\\to$ <strong>118 tokens/s</strong> ($4.2\\times$ speedup).</li>\n    <li><strong>AST Verification:</strong> 100.0% pass rate observed across deterministic algorithmic benchmark suites (0% reward-hacking escapes under the verifier test suite).</li>\n  </ul>\n\n  <h2>6. Conclusion</h2>\n  <p>\n    <strong>KOMPRESS v2</strong> unifies multi-teacher geometric-mean consensus distillation, random matrix spectral rigidity null models, and multi-agent AST worktree verification into a principled edge reasoning framework. By proving the exact equivalence between logit averaging and geometric-mean probability consensus, we provide a solid mathematical foundation for sovereign, ultra-low-latency edge intelligence.\n  </p>\n\n  <h2>References</h2>\n  <ol class=\"references\">\n    <li>Péter Lodri. <em>KOMPRESS: High-Throughput Token Compression and Ternary Representations</em>. 8b.is Technical Report, 2025.</li>\n    <li>Péter Lodri. <em>Axiom Quant: Spectral Rigidity, Random Matrices, and Process Ontology</em>. Axiom Quant Monographs, 2026.</li>\n    <li>Zhidong Bai and Jack W. Silverstein. <em>Spectral Analysis of Large Dimensional Random Matrices</em>. Springer, 2010.</li>\n  </ol>\n\n</body>\n</html>\n";
}
